# ---------------------------------------------------------------------------
# 4. HELPERS: training prompt + exports
# ---------------------------------------------------------------------------
SYSTEM_PROMPT = f"""You are the virtual assistant for {BUSINESS_NAME}.
Answer only using the approved Q&A knowledge below. Be warm, concise, and clear.
Never give medical diagnoses, legal advice, or guarantee insurance coverage.
If you do not know, say so and direct the person to call {PHONE}."""


def build_training_prompt(items: List[QAItem] = QA_ITEMS) -> str:
    """Return one text block to feed an AI agent as its knowledge base."""
    blocks = [SYSTEM_PROMPT, "", "APPROVED Q&A:"]
    for it in items:
        blocks.append(f"[{it.topic}] Q: {it.question}\nA: {it.answer}\n")
    return "\n".join(blocks)


def export_json(path: str = "first_rehab_qa.json") -> None:
    """JSON for the developer to render as HTML (accordion, FAQ page, etc.)."""
    with open(path, "w", encoding="utf-8") as f:
        json.dump([asdict(i) for i in QA_ITEMS], f, indent=2, ensure_ascii=False)


def export_html_ready() -> dict:
    """Group by topic: {topic: [{q, a}, ...]}, ready to loop over in a template."""
    grouped: dict = {}
    for it in QA_ITEMS:
        grouped.setdefault(it.topic, []).append({"q": it.question, "a": it.answer})
    return grouped


def find_answer(user_text: str) -> QAItem | None:
    """Naive keyword matcher; shows how `keywords` would be used in retrieval."""
    text = user_text.lower()
    best, best_score = None, 0
    for it in QA_ITEMS:
        score = sum(1 for k in it.keywords if k.lower() in text)
        if score > best_score:
            best, best_score = it, score
    return best


if __name__ == "__main__":
    for topic, rows in export_html_ready().items():
        print(f"\n=== {topic} ===")
        for r in rows:
            print(f"Q: {r['q']}\nA: {r['a']}\n")
    print("Pending review:", [i.id for i in QA_ITEMS if i.needs_review])
    print("Sample match:", find_answer("do you take medicare?").question)
